"Xi'an", "Hong Kong"};

// lh和rh表示查找范围，返回出现的位置
int binarySearch(char *cityTable[], int lh, int rh, char *cityName)
{
    int mid, result;
    if (lh <= rh) {
        mid = (lh + rh) / 2;
        result = strncmp(cityTable[mid], cityName, strlen(cityName));
        if (result == 0)
            return mid; // 找到
        else if (result > 0)
            return binarySearch(cityTable, lh, mid - 1, cityName);
        else
            return binarySearch(cityTable, mid + 1, rh, cityName);
    }
    return -1; // 没有找到
}

