关键问题

将快速排序设计成一个函数模板,将待排序的数据类型设计成模板参数;不同类型的数据有不同的比较方式,向排序函数传递不同的比较函数来解决

```cpp
template <class T>
void quicksort(T data[], int low, int high,
```

```cpp
template <class T>
int divide (T data[], int low, int high, int (*comp)(T, T))
{
 T k = data[low];
 do {
 while (low < high && comp(data[high], k)>0)
 --high;
 if (low < high) { data[low] = data[high]; ++low;}
 while (low < high && comp(data[low], k) < 0)
 ++low;
 if (low < high) { data[high] = data[low]; --high; }
 } while (low != high);
 divide()
 data[low] = k;
}
return low;
```

